"„Die Mauer hält die Monster draußen. Solange du drinnen bist, bist du sicher.“": "„A muralha mantém os monstros lá fora. Enquanto estiveres cá dentro, estás seguro.“",
"„Die Wildschweine fressen mir die Rüben weg. Wenn du welche siehst, jag sie!“": "„Os javalis comem-me os nabos. Se vires algum, caça-o!“",
"„Hast du schon mal einen Drachen gesehen? Lian sagt, am Feuerberg gibt es welche.“": "„Já viste algum dragão? A Lian diz que há alguns na Montanha de Fogo.“",
"„Früher war Kazehana eine ruhige Stadt. Dann kamen die Steine.“": "„Kazehana era uma cidade calma. Depois vieram as pedras.“",
"„Jeder Stein hat seine eigene Seele. Und jeder lässt etwas anderes zurück.“": "„Cada pedra tem a sua própria alma. E cada uma deixa algo diferente para trás.“",
