"Die große Stadt Kazehana mit den grünen Sonnenwiesen.": "A grande cidade de Kazehana com os verdes Prados Solares.",
"Dichter Nadelwald mit Banditen, Spinnen und Bären. Spinnenhöhle und Banditenkeller.": "Densa floresta de coníferas com bandidos, aranhas e ursos. Caverna das Aranhas e Cave dos Bandidos.",
"Staubiges Tal der Orks und Skorpione. Orkfestung.": "Vale poeirento de orcs e escorpiões. Fortaleza Orc.",
"Graue Aschenebene mit Ogern und Dämonen. Totengruft.": "Planície cinzenta de cinzas com ogres e demónios. Cripta dos Mortos.",
"Eisige Gipfel mit Eiswölfen, Yetis und Frostgeistern. Eisgrotte.": "Picos gelados com lobos de gelo, yetis e espíritos do gelo. Gruta de Gelo.",
"Nebliges Moor voller Untoter, Hexen und Ghule.": "Pântano nebuloso cheio de mortos-vivos, bruxas e ghouls.",
"Schwarzer Basalt und Lavaflüsse, Golems, Feuerdämonen und Drachen. Drachenhort.": "Basalto negro e rios de lava, golems, demónios de fogo e dragões. Covil do Dragão.",
"Du wirbelst um dich selbst, triffst alle Gegner im Umkreis und betäubst sie kurz.": "Giras sobre ti mesmo, atinges todos os inimigos à volta e atordoa-los brevemente.",
"Buff: Blitze zucken um dich. Mehr Angriffstempo und Lauftempo.": "Buff: relâmpagos crepitam à tua volta. Mais velocidade de ataque e de movimento.",
"Erdbeben": "Terramoto",
"Du stampfst auf und der Boden bebt: Alle Gegner um dich werden {0} s betäubt.": "Bates com o pé e o chão treme: todos os inimigos à tua volta ficam atordoados {0} s.",
"Starker Körper": "Corpo Forte",
"Buff: Dein Körper wird hart wie Stein. Mehr Verteidigung und weniger erlittener Schaden.": "Buff: o teu corpo fica duro como pedra. Mais defesa e menos dano sofrido.",
"Geistesschlag": "Golpe Espiritual",
"Ein gebündelter Schlag mit voller Kraft auf ein einzelnes Ziel. Sehr hoher Schaden.": "Um golpe concentrado com toda a força num único alvo. Dano muito elevado.",
"Kriegsschrei": "Grito de Guerra",
"Ein Schrei, der Gegner lähmt: Sie werden langsamer und nehmen mehr Schaden.": "Um grito que paralisa os inimigos: ficam mais lentos e sofrem mais dano.",
"Du drehst dich mit beiden Dolchen und triffst alle Gegner um dich.": "Giras com ambas as adagas e atinges todos os inimigos à tua volta.",
"Schattensprung": "Salto Sombrio",
"Du springst durch die Schatten nach vorn und schneidest alles auf dem Weg.": "Saltas pelas sombras para a frente e cortas tudo pelo caminho.",
"Lähmende Klinge": "Lâmina Paralisante",
"Ein Stich in die Sehnen: Das Ziel ist {0} s betäubt und {1} s vergiftet.": "Uma estocada nos tendões: o alvo fica atordoado {0} s e envenenado {1} s.",
"Schattenmantel": "Manto Sombrio",
"Buff: Schatten hüllen dich ein. Mehr Ausweichen und mehr kritische Treffer.": "Buff: as sombras envolvem-te. Mais esquiva e mais golpes críticos.",
"Buff: Drachenkraft fließt in dich. Mehr Angriff und mehr Fertigkeitsschaden.": "Buff: a força do dragão flui em ti. Mais ataque e mais dano de perícia.",
"Geisterfaust": "Punho Espiritual",
"Eine Faust aus Geisterkraft trifft ein Ziel und betäubt es {0} s.": "Um punho de força espiritual atinge um alvo e atordoa-o {0} s.",
"Windfessel": "Grilhão de Vento",
"Wirbelnder Wind fesselt Gegner um dich: Sie werden langsamer und verwundbar.": "Um vento rodopiante prende os inimigos à tua volta: ficam mais lentos e vulneráveis.",
"Segen": "Bênção",
"Buff: Weniger erlittener Schaden, Leben regeneriert sich, mehr kritische Treffer.": "Buff: menos dano sofrido, a vida regenera-se, mais golpes críticos.",
"Heilung": "Cura",
"Heilt einen Teil deines Lebens und gibt dir danach mehr Angriff.": "Cura parte da tua vida e depois dá-te mais ataque.",
