"Die Wölfe werden mutiger. Dünne das Rudel aus, ehe sie das Tor erreichen.": "Os lobos estão mais ousados. Reduz a alcateia antes que cheguem ao portão.",
"Verirrte Hirsche": "Veados Perdidos",
"Der Alpha": "O Alfa",
"Hinter den Wölfen stehen ihre Anführer, die Alpha-Wölfe. Ohne sie zerfällt das Rudel.": "Por trás dos lobos estão os seus líderes, os lobos alfa. Sem eles, a alcateia desfaz-se.",
