"Schützen im Dickicht": "Atiradores no Matagal",
"Aus den Baumkronen schießen Banditen auf alles, was sich bewegt. Hol sie herunter.": "Do alto das árvores, bandidos disparam contra tudo o que se mexe. Deita-os abaixo.",
"Netz der Spinnen": "Teia de Aranhas",
"Stein der Gier": "Pedra da Ganância",
"Zwei Steine der Gier locken Banditen an wie Gold die Diebe. Zerschlage sie.": "Duas Pedras da Ganância atraem bandidos como o ouro atrai ladrões. Destrói-as.",
"Lautlose Jäger": "Caçadores Silenciosos",
"Luchse reißen unsere Späher, ohne dass einer sie kommen sieht. Sei wachsamer als sie.": "Os linces matam os nossos batedores sem que ninguém os veja chegar. Sê mais atento do que eles.",
"Der Banditenfürst": "O Senhor dos Bandidos",
"Der Braunbär": "O Urso Pardo",
"Ein Rudel Braunbären hat den Holzfällerpfad besetzt. Sie sind stark, sei vorsichtig.": "Um bando de ursos pardos ocupou o trilho dos lenhadores. São fortes, tem cuidado.",
