"Kapitel {0} · Rostschlucht": "Capítulo {0} · Garganta Ferrugem",
"Hyänen der Orks": "Hienas dos Orcs",
"Die Schamanen": "Os Xamãs",
"Ihre Schamanen rufen Flüche über das Tal. Ohne sie verlieren die Orks ihren Mut.": "Os seus xamãs lançam maldições sobre o vale. Sem eles, os orcs perdem a coragem.",
"Stein der Schwärze": "Pedra da Escuridão",
"Die Orks beten schwarze Steine an. Nimm ihnen ihre Götzen.": "Os orcs adoram pedras negras. Tira-lhes os seus ídolos.",
"Stachel im Sand": "Ferrão na Areia",
"In den Felsspalten nisten Riesenskorpione. Ihr Gift lähmt einen Ochsen. Räum die Spalten.": "Nas fendas das rochas nidificam escorpiões gigantes. O seu veneno paralisa um boi. Limpa as fendas.",
"Der Ork-Hauptmann": "O Capitão Orc",
"Ohne ihre Hauptmänner sind die Orks nur ein wilder Haufen. Finde sie.": "Sem os seus capitães, os orcs são só um bando selvagem. Encontra-os.",
"Stein der Asche": "Pedra das Cinzas",
"Der Stein der Asche verbrennt das Tal von innen. Lösch ihn aus, bevor nur Staub bleibt.": "A Pedra das Cinzas queima o vale por dentro. Apaga-a antes que só reste pó.",
"Asche über dem Ödland": "Cinzas sobre o Ermo",
"Oger im Aschenfeld": "Ogres no Campo de Cinzas",
"Thrak hatte recht, dich zu schicken. Oger plündern unser Lager jede Nacht. Halte sie fern.": "O Thrak fez bem em enviar-te. Os ogres saqueiam o nosso acampamento todas as noites. Mantém-nos longe.",
"Kapitel {0} · Ödland": "Capítulo {0} · Ermo",
"Wargrudel": "Matilha de Wargs",
"Wargs folgen den Ogern und fressen, was diese übrig lassen. Jag das Rudel.": "Os wargs seguem os ogres e comem o que eles deixam. Caça a matilha.",
"Dämonen im Ödland": "Demónios no Ermo",
"Aus den Rissen im Ödland steigen Dämonen. Treib sie zurück in die Tiefe.": "Das fendas do Ermo sobem demónios. Empurra-os de volta para as profundezas.",
"Stein der Glut": "Pedra das Brasas",
"Die Steine der Glut lassen das Ödland brennen. Lösche sie aus.": "As Pedras das Brasas fazem arder o Ermo. Apaga-as.",
"Höllenhunde": "Cães Infernais",
"Dreiköpfige Hunde bewachen die Risse. Wer sie besiegt, kann den Rissen nahe kommen.": "Cães de três cabeças guardam as fendas. Quem os derrotar pode aproximar-se das fendas.",
"Die Oase im Süden": "O Oásis do Sul",
"Kobras in der Wüste": "Cobras no Deserto",
"Kapitel {0} · Schlangental": "Capítulo {0} · Vale das Serpentes",
"Das Rasseln im Sand": "O Chocalhar na Areia",
"Stein der Schatten": "Pedra das Sombras",
"Im Dschungel würgen Pythons ganze Ochsen. Wer dort Holz schlägt, kommt nicht wieder.": "Na selva, as pítons estrangulam bois inteiros. Quem lá corta lenha não volta.",
"Schwarze Panther": "Panteras Negras",
"Die Panther der Nagas jagen in der Nacht. Mach den Dschungel wieder sicher.": "As panteras dos nagas caçam de noite. Torna a selva segura outra vez.",
"Eis im Norden": "Gelo no Norte",
"Eiswölfe": "Lobos de Gelo",
"Hakim hat dich geschickt? Gut. Eiswölfe umkreisen unser Lager, sie riechen jede Schwäche.": "Foi o Hakim que te enviou? Ótimo. Lobos de gelo rondam o acampamento e farejam qualquer fraqueza.",
"Kapitel {0} · Frostgipfel": "Capítulo {0} · Picos Gelados",
"Der Yeti": "O Yeti",
"Stein des Frostes": "Pedra do Gelo",
"Zwei Steine des Frostes lassen den Gipfel nie mehr tauen. Zerschlage sie.": "Duas Pedras do Gelo impedem o pico de alguma vez degelar. Destrói-as.",
"Wilde Mammuts": "Mamutes Selvagens",
"Frostgeister": "Espíritos do Gelo",
"In den Schneestürmen wandern Geister. Wer sie berührt, erfriert von innen.": "Nas tempestades de neve vagueiam espíritos. Quem lhes toca congela por dentro.",
"Stein der Stille": "Pedra do Silêncio",
"Der Eiskönig": "O Rei do Gelo",
"Alles Eis gehorcht dem Eiskönig in der Eisgrotte. Bezwinge ihn, dann taut der Gipfel.": "Todo o gelo obedece ao Rei do Gelo na Gruta de Gelo. Derrota-o e o pico degela.",
"Nebel über dem Moor": "Névoa sobre o Pântano",
"Das Totenmoor": "O Pântano dos Mortos",
"Kapitel {0} · Totenmoor": "Capítulo {0} · Pântano dos Mortos",
"Moorwölfe": "Lobos do Pântano",
"Die Wölfe hier sind halb tot und hören nicht auf zu jagen. Gib ihnen den Rest.": "Os lobos daqui estão meio mortos e não param de caçar. Acaba com eles.",
"Die Sumpfhexen": "As Bruxas do Pântano",
"Hexen beschwören die Toten aus dem Schlamm. Ohne sie bleiben die Gräber zu.": "As bruxas invocam os mortos da lama. Sem elas, as campas ficam fechadas.",
"Stein der Fäulnis": "Pedra da Podridão",
"Zwei Steine der Fäulnis vergiften das Wasser. Nichts Lebendes wächst mehr.": "Duas Pedras da Podridão envenenam a água. Já nada vivo cresce.",
"Ghule": "Ghouls",
"Die Ghule fressen, was die Hexen erwecken. Sie sind schnell und hungrig. Sei schneller.": "Os ghouls devoram o que as bruxas despertam. São rápidos e famintos. Sê mais rápido.",
"Donner in der Klamm": "Trovão na Ravina",
"Oswin hat dich geschickt? Die Trolle belagern die Klamm. Zeig ihnen unsere Stärke.": "Foi o Oswin que te enviou? Os trolls cercam a ravina. Mostra-lhes a nossa força.",
"Kapitel {0} · Donnerklamm": "Capítulo {0} · Ravina do Trovão",
"Harpyien": "Harpias",
"Harpyien stoßen auf jeden herab, der den Pass hinaufsteigt. Hol sie aus der Luft.": "As harpias atacam quem sobe o desfiladeiro. Deita-as do céu abaixo.",
"Die Minotauren": "Os Minotauros",
"Minotauren rennen mit gesenkten Hörnern gegen unsere Tore. Halte sie auf.": "Os minotauros investem de chifres baixos contra os nossos portões. Trava-os.",
"Stein der Pein": "Pedra do Tormento",
"Blutrote Steine wachsen aus den Felsen. Sie nähren sich von Schmerz.": "Pedras vermelho-sangue crescem das rochas. Alimentam-se da dor.",
"Erwachte Titanen": "Titãs Despertos",
"Auf dem Titanenkamm stehen die Steintitanen auf. Bring sie wieder zum Stehen – für immer.": "Na Crista dos Titãs, os titãs de pedra erguem-se. Fá-los parar – para sempre.",
"Der Berg brennt": "A Montanha Arde",
"Lavagolems": "Golems de Lava",
"Gunhild schickt dich? Dann bist du bereit. Golems aus Lava wälzen sich auf unser Lager zu.": "A Gunhild enviou-te? Então estás pronto. Golems de lava avançam sobre o nosso acampamento.",
"Kapitel {0} · Feuerberg": "Capítulo {0} · Montanha de Fogo",
"Glutkatzen": "Gatos das Brasas",
"Glutkatzen streifen durch die Lavafelder. Wo sie laufen, brennt der Boden.": "Os gatos das brasas rondam os campos de lava. Por onde passam, o chão arde.",
"Stein der Flamme": "Pedra da Chama",
"Zwei Steine der Flamme heizen den Berg an. Ohne sie verlöschen die Lavaflüsse.": "Duas Pedras da Chama aquecem a montanha. Sem elas, os rios de lava apagam-se.",
"Feuerdämonen": "Demónios de Fogo",
"Aus den Kratern steigen Feuerdämonen. Treib sie zurück ins Feuer.": "Das crateras sobem demónios de fogo. Empurra-os de volta para o fogo.",
"Feuerdrachen": "Dragões de Fogo",
"Am Feuerberg nisten Drachen. Wenn sie flügge werden, ist kein Dorf mehr sicher.": "Na Montanha de Fogo nidificam dragões. Quando aprenderem a voar, nenhuma aldeia estará segura.",
"Stein des Untergangs": "Pedra da Ruína",
"Heimkehr nach Kazehana": "Regresso a Kazehana",
