"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "Mal os cães se foram, as raposas rondam os estábulos. Expulsa-as de volta para os prados",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "Os javalis comem a colheita dos camponeses. Um inverno sem provisões seria o nosso fim",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "Na orla dos prados brilha uma pedra da fúria. A sua fúria enlouquece os animais – parte-a",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "Ainda bem que o Bao te envia. Bandidos assaltam cada mercador no caminho da floresta. Expulsa-os",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "Os javalis daqui têm espinhos em vez de cerdas. Despedaçam as nossas armadilhas – e os caçadores",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "No fundo da floresta, aranhas gigantes tecem teias sobre os caminhos. Queima-as se for preciso",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "No meio da floresta cresce uma pedra de espinhos. As suas silvas sufocam cada árvore. Destrói-a",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "O Hagen envia-te? Então vem, os orcs já estão diante das paliçadas. Enfraquece o exército deles",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "Os orcs criam hienas como cães e lançam-nas contra os nossos batedores. Acaba com a matilha",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "O Idris envia-te? Os deuses são bons para Sahra. As cobras espreitam em cada poço",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "Ouves esse chocalhar? Cascavéis. Centenas. As caravanas já não se atrevem a partir",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "No Pico Gelado viram-se yetis do tamanho de casas. Traz as peles deles como prova",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "Os mamutes estão furiosos desde que o frio não cede. Esmagam as nossas cabanas de provisões",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Onde está a pedra do silêncio, toda a canção se cala. Traz o som de volta ao cume",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "A última e mais poderosa de todas as pedras da alma. Destrói-a e as pedras deixarão de crescer",
